import{_ as o,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2017-JUN-01 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-JUN-01 :: Ceph Performance Weekly","date":"2017-06-21T00:00:00.000Z","updated":"2017-06-22T00:00:00.000Z","tags":["Ceph","分布式存储","BlueStore","RocksDB","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-JUN-01_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-JUN-01_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),s={name:"posts/2017/2017-JUN-01_-_-_Ceph_Performance_Weekly.md"};function n(i,e,p,_,a,g){return t(),r("div",null,[...e[0]||(e[0]=[l("<p>本次会议主要讨论了Ceph分布式存储项目的性能优化和改进方向。以下是会议的关键内容：</p><p><strong>一、Ceph项目进展</strong></p><ol><li><strong>Polar Quest</strong>： 将trim操作移动到mem thread线程，以提高内存使用效率。</li><li><strong>内存优化</strong>： 通过优化inline memory功能，提高内存使用效率。</li><li><strong>缓存管理</strong>： 新增5个缓存池，用于BlueStore，提高数据可见性和跟踪。</li><li><strong>B-Tree优化</strong>： 使用B-Tree替代STL map，提高PG temp mapping效率。</li><li><strong>BlueStore限流优化</strong>： 通过消除无用计算和清理代码，提高BlueStore性能。</li><li><strong>内存复用</strong>： 通过rocksdb glue API，实现内存复用，提高性能。</li><li><strong>同步提交</strong>： 实现同步提交功能，提高事务提交效率。</li></ol><p><strong>二、讨论议题</strong></p><ol><li><strong>新存储引擎</strong>： 随着元数据增长，BlueStore性能出现瓶颈。讨论了通过增加缓存大小、优化内存管理等方案来提高性能。</li><li><strong>SSD选择</strong>： 讨论了SSD选择和性能问题，以及如何应对SSD寿命和性能之间的权衡。</li><li><strong>数据丢失问题</strong>： 讨论了RBD数据丢失问题，以及如何通过优化复制机制和更新语义来提高数据可靠性。</li><li><strong>RocksDB后端</strong>： 讨论了使用RocksDB作为后端存储的可行性，以及如何简化更新语义和复制逻辑。</li></ol><p><strong>三、决定事项</strong></p><ol><li>继续优化BlueStore性能，包括增加缓存大小、优化内存管理等。</li><li>考虑使用RocksDB作为后端存储，简化更新语义和复制逻辑。</li><li>提交相关PR，并进行测试验证。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>继续关注BlueStore性能问题，并进行相关优化。</li><li>研究RocksDB后端存储的可行性，并提交相关PR。</li><li>跟踪RBD数据丢失问题的修复进度。</li></ol><p><strong>五、其他事项</strong></p><ol><li>讨论了PVC构建问题，以及如何解决PowerPC优化和编译问题。</li><li>讨论了RTC分支和同步提交功能，以及其适用场景。</li></ol><p>本次会议确定了优化BlueStore性能、简化更新语义和复制逻辑等关键任务，并制定了相应的行动计划，旨在进一步提高Ceph分布式存储的性能和可靠性。</p>",12)])])}const S=o(s,[["render",n]]);export{m as __pageData,S as default};
